1	package posemap
2	
3	import (
4		"math"
5		"sort"
6	)
7	
8	// poseShift 描述一次回环校正对轨迹施加的同一次刚体重定位：锚点落到目标
9	// 位置、朝向归一到 [-π,π)；从锚点到末帧的其余帧与锚点一起平移旋转，保留
10	// 各帧相对锚点的位置关系与朝向差。提交校正（Correct）与打开地图时的校正
11	// 记录几何核对（validateLoaded，见 persistence.go）共用这同一份规则与
12	// 运算次序，两处对“校正后位置与朝向”的理解因此始终一致。
13	type poseShift struct {
14		x, y       float64 // 目标位置，即锚点校正后位置
15		heading    float64 // 目标朝向归一到 [-π,π)，即锚点校正后朝向
16		anchorX    float64 // 锚点校正前位置
17		anchorY    float64
18		dHeading   float64 // 归一后的最短朝向差，即各帧叠加的旋转角
19		cosD, sinD float64 // 旋转角的余弦与正弦
20		identity   bool    // 只调方差的恒等校正：位置与朝向保持原值
21	}
22	
23	// newPoseShift 按提交目标与锚点校正前位姿构造重定位。目标朝向先归一，
24	// 旋转角取归一后的最短朝向差。目标位置与锚点原位置完全相同、目标朝向归
25	// 一后与原朝向等价（旋转角为 0）时是恒等校正：几何上没有任何平移或旋
26	// 转，校正前后位姿必须完全相同。恒等校正不能套用旋转平移公式——公式会
27	// 先求相对锚点的偏移，轨迹横跨 ±1e308 这类大坐标时该差值先溢出为
28	// ±Inf、再参与浮点运算退化为 NaN，使本应成功的校正被误判为数值异常；
29	// 恒等校正直接保留原位姿。
30	func newPoseShift(tgt CorrectionTarget, anchorBefore Pose) poseShift {
31		heading := normalizeAngle(tgt.Heading)
32		dHeading := normalizeAngle(heading - anchorBefore.Heading)
33		return poseShift{
34			x:        tgt.X,
35			y:        tgt.Y,
36			heading:  heading,
37			anchorX:  anchorBefore.X,
38			anchorY:  anchorBefore.Y,
39			dHeading: dHeading,
40			cosD:     math.Cos(dHeading),
41			sinD:     math.Sin(dHeading),
42			identity: dHeading == 0 && tgt.X == anchorBefore.X && tgt.Y == anchorBefore.Y,
43		}
44	}
45	
46	// apply 计算一帧校正后的位置与朝向：恒等校正原样保留校正前值；否则把校
47	// 正前相对锚点的偏移随锚点一起旋转平移，朝向叠加同一旋转角并归一到
48	// [-π,π)。帧时间与方差不属于几何规则，由调用方处理。
49	func (s poseShift) apply(before Pose) (x, y, heading float64) {
50		if s.identity {
51			return before.X, before.Y, before.Heading
52		}
53		dx := before.X - s.anchorX
54		dy := before.Y - s.anchorY
55		return s.x + s.cosD*dx - s.sinD*dy,
56			s.y + s.sinD*dx + s.cosD*dy,
57			normalizeAngle(before.Heading + s.dHeading)
58	}
59	
60	// Correct 提交一次已确认回环校正。
61	//
62	// req.ID 必须非空；req.Anchor 必须准确命中一个已导入帧的时间（不能是
63	// 初始位姿，也不借用历史查询得到的最近一帧）；目标位姿数值必须有限、
64	// 目标方差必须非负。命中后，锚点帧采用提交的位姿；从锚点到提交时末帧
65	// 的轨迹整体平移并旋转（保持这些帧在校正前彼此的相对位置与朝向，时间
66	// 不变，朝向归一到既有范围）；锚点之后每帧的方差等于目标方差加上锚点
67	// 之后至该帧的原运动方差累计值。更早的位姿不变。
68	//
69	// 受影响帧中的路标观测随新位姿改变地图位置；更早观测的地图位置不变。
70	// 同一路标仍按全部已接受观测、依原时间与同帧输入次序做增量平均并遵守
71	// 合并距离限制；观测次数不变。若校正后出现路标冲突，整次校正拒绝并说
72	// 明冲突帧时间与路标。输入或校正结果含非有限数值同样拒绝；观测转换到
73	// 地图坐标后溢出为 NaN/无穷时按数值异常拒绝，说明该观测所在帧的实际
74	// 时间、路标标识与出现编号，而不是误报为距离冲突。
75	//
76	// 同一标识以相同内容重复提交返回首次结果且不再修改数据；同一标识不同
77	// 内容明确拒绝。任何拒绝或保存失败都不改变轨迹、路标与既有校正记录。
78	// 旧文件缺少逐帧观测来源时，覆盖其历史范围的校正返回 RejectNoBasis。
79	func (m *Map) Correct(req Correction) (CorrectionRecord, error) {
80		m.mu.Lock()
81		defer m.mu.Unlock()
82		if m.closed {
83			return CorrectionRecord{}, ErrClosed
84		}
85		st := m.state
86	
87		// 已保存校正：相同内容直接返回首次记录；不同内容明确拒绝。
88		// 不做任何校验或状态变更，即使其后又提交过其他校正。
89		if hash, ok := st.corrIndex[req.ID]; ok {
90			if hash == canonicalCorrectionHash(req.Anchor, req.Target) {
91				return cloneRecord(st.correctionRecordByID(req.ID)), nil
92			}
93			return CorrectionRecord{}, &RejectError{Kind: RejectCorrectionMismatch, Landmark: req.ID, HasLandmark: true}
94		}
95	
96		if req.ID == "" {
97			return CorrectionRecord{}, &RejectError{Kind: RejectEmptyID}
98		}
99		tgt := req.Target
100		if !isFinite(tgt.X) || !isFinite(tgt.Y) || !isFinite(tgt.Heading) || !isFinite(tgt.Variance) {
101			return CorrectionRecord{}, &RejectError{Kind: RejectNonFinite, Time: req.Anchor, HasTime: true}
102		}
103		if tgt.Variance < 0 {
104			return CorrectionRecord{}, &RejectError{Kind: RejectNegativeVariance, Time: req.Anchor, HasTime: true}
105		}
106	
107		// 锚点必须准确命中已导入帧：trajectory[0] 是初始位姿，不能校正。
108		anchorIdx := -1
109		for j := 1; j < len(st.trajectory); j++ {
110			if st.trajectory[j].Time == req.Anchor {
111				anchorIdx = j
112				break
113			}
114		}
115		if anchorIdx < 0 {
116			return CorrectionRecord{}, &RejectError{Kind: RejectAnchorNotFound, Time: req.Anchor, HasTime: true}
117		}
118		end := len(st.trajectory) - 1
119	
120		// 受影响范围内每一帧都必须有逐帧依据（旧文件没有，不能靠推测校正）。
121		for k := anchorIdx - 1; k < len(st.sources); k++ {
122			if st.sources[k] == nil {
123				return CorrectionRecord{}, &RejectError{Kind: RejectNoBasis, Time: req.Anchor, HasTime: true}
124			}
125		}
126	
127		oldAnchor := st.trajectory[anchorIdx]
128		// 锚点到末帧的整体平移旋转规则（含只调方差的恒等情形）与打开地图时
129		// 的记录几何核对共享同一实现，见上方 poseShift。
130		shift := newPoseShift(tgt, oldAnchor)
131	
132		// ---- 在副本上推演新位姿，真实状态此时保持不变 ----
133		next := append([]Pose(nil), st.trajectory...)
134		accumVar := tgt.Variance
135		for j := anchorIdx; j <= end; j++ {
136			old := st.trajectory[j]
137			if j > anchorIdx {
138				accumVar += st.sources[j-1].moveVariance
139			}
140			x, y, heading := shift.apply(old)
141			np := Pose{
142				Time:     old.Time,
143				X:        x,
144				Y:        y,
145				Heading:  heading,
146				Variance: accumVar,
147			}
148			if !isFinite(np.X) || !isFinite(np.Y) || !isFinite(np.Heading) || !isFinite(np.Variance) {
149				return CorrectionRecord{}, &RejectError{Kind: RejectNonFinite, Time: req.Anchor, HasTime: true}
150			}
151			next[j] = np
152		}
153	
154		// 重放器：观测按帧时间归入当时那次出现、旧观测固定贡献作为起点、
155		// 逐条重建位置的规则与打开地图时的核对共享同一实现（见 replay.go）。
156		replay := newObservationReplay(st.config.MergeDistance)
157		for id, lm := range st.landmarks {
158			replay.track(id, lm.occurrenceWindows())
159		}
160		// 重放帧序列：受影响帧（锚点至末帧）用校正后位姿，更早帧用原位姿；
161		// 旧文件帧没有逐帧依据，其观测已计入对应出现的固定旧贡献，这里按
162		// 空观测帧处理。
163		frames := make([]replayFrame, 0, end)
164		for j := 1; j <= end; j++ {
165			var obs []Observation
166			if src := st.sources[j-1]; src != nil {
167				obs = src.observations
168			}
169			frames = append(frames, replayFrame{time: st.trajectory[j].Time, pose: next[j], observations: obs})
170		}
171	
172		// 受影响的路标出现：在受影响帧中被观测到的全部（标识，出现编号）。
173		// 回环校正跨越同一路标的多次出现时，各次出现分别聚合、分别遵守合并
174		// 距离限制；已接受观测必然属于某次出现。
175		affected := replay.observed(frames[anchorIdx-1:])
176		affectedKeys := make([]occurrenceKey, 0, len(affected))
177		for k := range affected {
178			affectedKeys = append(affectedKeys, k)
179		}
180		sort.Slice(affectedKeys, func(i, j int) bool {
181			if affectedKeys[i].id != affectedKeys[j].id {
182				return affectedKeys[i].id < affectedKeys[j].id
183			}
184			return affectedKeys[i].num < affectedKeys[j].num
185		})
186	
187		// 逐“出现”登记固定旧贡献：旧文件第 1 次出现的既有观测无法重放，
188		// 其贡献固定为文件中的聚合值（位置不随校正改变）；其余观测随帧序列
189		// 重放。同一路标的不同出现互不参与彼此的合并。
190		for _, k := range affectedKeys {
191			occ := st.landmarks[k.id].appearances[k.num-1]
192			replay.seed(k.id, k.num, occ.legacyCount, occ.legacyMX, occ.legacyMY)
193		}
194		// 目标、原始观测与校正后位姿都有限，转换结果仍可能因数值过大
195		// 溢出为 NaN/无穷。与导入一致：数值异常优先于距离冲突，按
196		// non_finite 拒绝并指出该观测所在帧的实际时间、路标标识与
197		// 其所属的出现编号（不是锚点时间），无论该次出现此前是否已有
198		// 观测、记录仍有效还是已失效。
199		if rej := replay.replay(frames); rej != nil {
200			switch rej.reason {
201			case replayNonFinite:
202				return CorrectionRecord{}, &RejectError{
203					Kind:          RejectNonFinite,
204					Time:          rej.time,
205					HasTime:       true,
206					Landmark:      rej.id,
207					HasLandmark:   true,
208					Occurrence:    rej.num,
209					HasOccurrence: true,
210				}
211			case replayConflict:
212				return CorrectionRecord{}, &RejectError{
213					Kind:          RejectLandmarkConflict,
214					Time:          rej.time,
215					HasTime:       true,
216					Landmark:      rej.id,
217					HasLandmark:   true,
218					Occurrence:    rej.num,
219					HasOccurrence: true,
220				}
221			default:
222				// 已接受观测必然属于某个已登记出现；归属失败说明内存不变量
223				// 被破坏，不可能由本包产生，按损坏处理而非半提交。
224				return CorrectionRecord{}, ErrCorrupt
225			}
226		}
227		for _, k := range affectedKeys {
228			a := replay.agg(k.id, k.num)
229			occ := st.landmarks[k.id].appearances[k.num-1]
230			if !isFinite(a.x) || !isFinite(a.y) {
231				return CorrectionRecord{}, &RejectError{Kind: RejectNonFinite, Time: req.Anchor, HasTime: true}
232			}
233			if a.count != occ.count {
234				// 内存不变量被破坏不可能由本包写出，按损坏处理而非半提交。
235				return CorrectionRecord{}, ErrCorrupt
236			}
237		}
238	
239		// ---- 组装校正前后快照（记录不可变） ----
240		rec := &CorrectionRecord{
241			ID:        req.ID,
242			Anchor:    req.Anchor,
243			Target:    tgt,
244			EndTime:   st.trajectory[end].Time,
245			Poses:     make([]PoseChange, 0, end-anchorIdx+1),
246			Landmarks: make([]LandmarkChange, 0, len(affectedKeys)),
247		}
248		for j := anchorIdx; j <= end; j++ {
249			rec.Poses = append(rec.Poses, PoseChange{Before: st.trajectory[j], After: next[j]})
250		}
251		for _, k := range affectedKeys {
252			occ := st.landmarks[k.id].appearances[k.num-1]
253			a := replay.agg(k.id, k.num)
254			rec.Landmarks = append(rec.Landmarks, LandmarkChange{
255				ID:         k.id,
256				Occurrence: k.num,
257				Before:     Landmark{ID: k.id, X: occ.x, Y: occ.y, Count: occ.count},
258				After:      Landmark{ID: k.id, X: a.x, Y: a.y, Count: a.count},
259			})
260		}
261	
262		// ---- 全部校验通过：暂存提交并落盘；落盘失败精确回滚 ----
263		oldTraj := append([]Pose(nil), st.trajectory...)
264		type occSnapshot struct {
265			key  occurrenceKey
266			occ  *occurrenceState
267			x, y float64
268		}
269		oldOcc := make([]occSnapshot, 0, len(affectedKeys))
270		for _, k := range affectedKeys {
271			occ := st.landmarks[k.id].appearances[k.num-1]
272			oldOcc = append(oldOcc, occSnapshot{key: k, occ: occ, x: occ.x, y: occ.y})
273		}
274		oldCorrLen := len(st.corrections)
275	
276		st.trajectory = next
277		for _, s := range oldOcc {
278			a := replay.agg(s.key.id, s.key.num)
279			s.occ.x, s.occ.y = a.x, a.y
280		}
281		st.corrections = append(st.corrections, rec)
282		st.corrIndex[req.ID] = canonicalCorrectionHash(req.Anchor, tgt)
283	
284		if err := m.saveReplace(); err != nil {
285			st.trajectory = oldTraj
286			for _, s := range oldOcc {
287				s.occ.x, s.occ.y = s.x, s.y
288			}
289			st.corrections = st.corrections[:oldCorrLen]
290			delete(st.corrIndex, req.ID)
291			return CorrectionRecord{}, err
292		}
293		return cloneRecord(rec), nil
294	}
295	
296	// Corrections 返回按提交次序排列的成功校正记录副本。记录一经生成永不
297	// 被后续校正改写；后续校正只是以当时最新状态为起点生成新记录。
298	func (m *Map) Corrections() ([]CorrectionRecord, error) {
299		m.mu.Lock()
300		defer m.mu.Unlock()
301		if m.closed {
302			return nil, ErrClosed
303		}
304		out := make([]CorrectionRecord, 0, len(m.state.corrections))
305		for _, rec := range m.state.corrections {
306			out = append(out, cloneRecord(rec))
307		}
308		return out, nil
309	}
310	
311	func (st *mapState) correctionRecordByID(id string) *CorrectionRecord {
312		for _, rec := range st.corrections {
313			if rec.ID == id {
314				return rec
315			}
316		}
317		return nil
318	}
319	
320	func cloneRecord(rec *CorrectionRecord) CorrectionRecord {
321		if rec == nil {
322			return CorrectionRecord{}
323		}
324		cp := *rec
325		cp.Poses = append([]PoseChange(nil), rec.Poses...)
326		cp.Landmarks = append([]LandmarkChange(nil), rec.Landmarks...)
327		return cp
328	}
