3	import (
4		"math"
5		"os"
6		"path/filepath"
7		"testing"
8	)
9	
10	// 输入全部为有限数值时，导入推演仍可能产生非有限结果：位置叠加、朝向
11	// 累计、方差累计溢出。这些情况必须按 non_finite 拒绝并指出从零开始的
12	// 帧序号，而不是在保存时返回普通编码错误。
13	func TestImportComputedNonFinitePose(t *testing.T) {
14		huge := func() Config {
15			return Config{
16				InitialTime: 0, InitialX: 1e308, InitialY: 0, InitialHeading: 0,
17				InitialVariance: 0, MaxInterval: 100, MergeDistance: 10,
18			}
19		}
20		type tc struct {
21			name   string
22			cfg    Config
23			frames []Frame
24			frame  int
25		}
26		cases := []tc{
27			{
28				name:   "position overflow on first frame",
29				cfg:    huge(),
30				frames: []Frame{{Time: 1, DX: 1e308}}, // 1e308 + 1e308 = +Inf
31				frame:  0,
32			},
33			{
34				name: "position overflow on later frame",
35				cfg:  huge(),
36				frames: []Frame{
37					{Time: 1}, // 1e308+1 舍入为 1e308，仍有限
38					{Time: 2},
39					{Time: 3, DX: 1e308}, // 这一帧才溢出
40				},
41				frame: 2,
42			},
43			{
44				name: "variance accumulation overflow",
45				cfg: func() Config {
46					c := huge()
47					c.InitialX = 0
48					c.InitialVariance = 1e308
49					return c
50				}(),
51				frames: []Frame{{Time: 1, MoveVariance: 1e308}}, // 1e308+1e308 = +Inf
52				frame:  0,
53			},
54			{
55				name: "heading accumulation overflow",
56				cfg: func() Config {
57					c := huge()
58					c.InitialX = 0
59					c.InitialHeading = 1e308
60					return c
61				}(),
62				frames: []Frame{{Time: 1, DHeading: 1e308}}, // 归一化后为 NaN
63				frame:  0,
64			},
65		}
66		for _, c := range cases {
67			t.Run(c.name, func(t *testing.T) {
68				m := newMap(t, c.cfg)
69				_, err := m.ImportSegment(Segment{ID: "s", Frames: c.frames})
70				r, ok := AsRejectError(err)
71				if !ok {
72					t.Fatalf("err = %v, want *RejectError", err)
73				}
74				if r.Kind != RejectNonFinite || !r.HasFrame || r.Frame != c.frame {
75					t.Fatalf("got kind=%q frame=%d(ok=%v), want non_finite frame %d", r.Kind, r.Frame, r.HasFrame, c.frame)
76				}
77				if r.HasLandmark {
78					t.Fatalf("pose rejection unexpectedly carries landmark %q", r.Landmark)
79				}
80				// 拒绝后当前位姿仍是初始位姿。
81				cur, _ := m.CurrentPose()
82				if cur.Time != 0 {
83					t.Fatalf("current time = %d, state leaked after rejection", cur.Time)
84				}
85			})
86		}
87	}
88	
89	// 观测转换到地图坐标后溢出时，无论该路标首次出现、失效后再次出现，还是
90	// 与有效记录（段内暂存或已提交记录）合并，都按 non_finite 拒绝并携带
91	// 路标标识；转换结果有限但超过合并距离时仍是原来的距离冲突。
92	func TestImportComputedNonFiniteObservation(t *testing.T) {
93		hugeCfg := Config{
94			InitialTime: 0, InitialX: 1e308, InitialY: 0, InitialHeading: 0,
95			InitialVariance: 0, MaxInterval: 100, MergeDistance: 10,
96		}
97	
98		t.Run("first appearance overflow", func(t *testing.T) {
99			m := newMap(t, hugeCfg)
100			_, err := m.ImportSegment(Segment{ID: "s", Frames: []Frame{
101				{Time: 1, Observations: []Observation{{ID: "L", X: 1e308}}}, // 地图 X = +Inf
102			}})
103			rejectKind(t, err, RejectNonFinite, 0, "L")
104			lms, _ := m.LandmarksInRect(Rect{MinX: -math.MaxFloat64, MinY: -math.MaxFloat64, MaxX: math.MaxFloat64, MaxY: math.MaxFloat64})
105			if len(lms) != 0 {
106				t.Fatalf("landmark leaked: %+v", lms)
107			}
108		})
109	
110		t.Run("in-segment merge overflow not conflict", func(t *testing.T) {
111			m := newMap(t, hugeCfg)
112			_, err := m.ImportSegment(Segment{ID: "s", Frames: []Frame{
113				{Time: 1, Observations: []Observation{{ID: "L", X: 0}}},     // 地图 (1e308,0)
114				{Time: 2, Observations: []Observation{{ID: "L", X: 1e308}}}, // 转换溢出
115			}})
116			rejectKind(t, err, RejectNonFinite, 1, "L")
117			lms, _ := m.LandmarksInRect(Rect{MinX: -math.MaxFloat64, MinY: -math.MaxFloat64, MaxX: math.MaxFloat64, MaxY: math.MaxFloat64})
118			if len(lms) != 0 {
119				t.Fatalf("staged landmark leaked after rejection: %+v", lms)
120			}
121			cur, _ := m.CurrentPose()
122			if cur.Time != 0 {
123				t.Fatalf("current time = %d, pose leaked", cur.Time)
124			}
125		})
126	
127		t.Run("merge with committed active overflow", func(t *testing.T) {
128			m := newMap(t, hugeCfg)
129			if _, err := m.ImportSegment(Segment{ID: "s1", Frames: []Frame{
130				{Time: 1, Observations: []Observation{{ID: "L", X: 0}}},
131			}}); err != nil {
132				t.Fatal(err)
133			}
134			_, err := m.ImportSegment(Segment{ID: "s2", Frames: []Frame{
135				{Time: 2, Observations: []Observation{{ID: "L", X: 1e308}}},
136			}})
137			rejectKind(t, err, RejectNonFinite, 0, "L")
138			// 已提交记录的观测次数不被暂存合并改变。
139			h, err := m.LandmarkAppearances("L")
140			if err != nil || len(h.Appearances) != 1 || h.Appearances[0].Landmark.Count != 1 {
141				t.Fatalf("committed count changed: %+v %v", h, err)
142			}
143		})
144	
145		t.Run("reappearance after invalidation overflow", func(t *testing.T) {
146			m := newMap(t, hugeCfg)
147			if _, err := m.ImportSegment(Segment{ID: "s1", Frames: []Frame{
148				{Time: 1, Observations: []Observation{{ID: "L", X: 0}}},
149			}}); err != nil {
150				t.Fatal(err)
151			}
152			if _, err := m.Invalidate(Invalidation{ID: "iv", Reason: "gone", Landmarks: []string{"L"}}); err != nil {
153				t.Fatal(err)
154			}
155			// 失效后再次出现：转换溢出同样按数值异常拒绝。
156			_, err := m.ImportSegment(Segment{ID: "s2", Frames: []Frame{
157				{Time: 2, Observations: []Observation{{ID: "L", X: 1e308}}},
158			}})
159			rejectKind(t, err, RejectNonFinite, 0, "L")
160			h, _ := m.LandmarkAppearances("L")
161			if len(h.Appearances) != 1 || h.Appearances[0].Active {
162				t.Fatalf("rejection consumed an occurrence number: %+v", h)
163			}
164		})
165	
166		t.Run("finite but beyond merge distance stays conflict", func(t *testing.T) {
167			cfg := hugeCfg
168			cfg.MergeDistance = 1
169			m := newMap(t, cfg)
170			if _, err := m.ImportSegment(Segment{ID: "s1", Frames: []Frame{
171				{Time: 1, Observations: []Observation{{ID: "L", X: 0}}}, // 地图 1e308
172			}}); err != nil {
173				t.Fatal(err)
174			}
175			// 地图坐标 1.1e308，有限但与既有均值相距 1e307，超出合并距离。
176			_, err := m.ImportSegment(Segment{ID: "s2", Frames: []Frame{
177				{Time: 2, Observations: []Observation{{ID: "L", X: 1e307}}},
178			}})
179			rejectKind(t, err, RejectLandmarkConflict, 0, "L")
180		})
181	}
182	
183	// 拒绝保持原子性：即使异常出现在后面的帧，前面暂存的位姿、新路标和观测
184	// 次数都不可见；已提交地图和本地数据文件保持原样；失败不消耗段标识，
185	// 也不消耗失效后再次出现的出现编号。
186	func TestImportComputedNonFiniteAtomicity(t *testing.T) {
187		path := filepath.Join(t.TempDir(), "map.bin")
188		cfg := Config{
189			InitialTime: 0, InitialX: 1e308, InitialY: 0, InitialHeading: 0,
190			InitialVariance: 0, MaxInterval: 100, MergeDistance: 10,
191		}
192		m, err := Create(path, cfg)
193		if err != nil {
194			t.Fatalf("Create: %v", err)
195		}
196		defer m.Close()
197	
198		if _, err := m.ImportSegment(Segment{ID: "s1", Frames: []Frame{
199			{Time: 1, Observations: []Observation{{ID: "L", X: 0}}},
200		}}); err != nil {
201			t.Fatal(err)
202		}
203		if _, err := m.Invalidate(Invalidation{ID: "iv", Reason: "gone", Landmarks: []string{"L"}}); err != nil {
204			t.Fatal(err)
205		}
206	
207		before, err := os.ReadFile(path)
208		if err != nil {
209			t.Fatal(err)
210		}
211	
212		// 异常出现在第 2 帧（帧序号 1）：第 0 帧的暂存位姿与观测必须随拒绝丢弃。
213		_, err = m.ImportSegment(Segment{ID: "s2", Frames: []Frame{
214			{Time: 2, Observations: []Observation{{ID: "N", X: 0}}},
215			{Time: 3, Observations: []Observation{{ID: "L", X: 1e308}}},
216		}})
217		rejectKind(t, err, RejectNonFinite, 1, "L")
218	
219		// 当前位姿仍是上一段末帧；新路标 N 不可见；L 仍处于失效状态且只有 1 次出现。
220		cur, _ := m.CurrentPose()
221		if cur.Time != 1 {
222			t.Fatalf("current time = %d, staged pose leaked", cur.Time)
223		}
224		if h, err := m.LandmarkAppearances("N"); err == nil {
225			t.Fatalf("staged new landmark N leaked: %+v", h)
226		}
227		h, _ := m.LandmarkAppearances("L")
228		if len(h.Appearances) != 1 || h.Appearances[0].Active {
229			t.Fatalf("occurrence number consumed by failed import: %+v", h)
230		}
231	
232		// 本地数据文件字节不变。
233		after, err := os.ReadFile(path)
234		if err != nil {
235			t.Fatal(err)
236		}
237		if len(after) != len(before) {
238			t.Fatalf("data file changed size: %d -> %d", len(before), len(after))
239		}
240		for i := range before {
241			if before[i] != after[i] {
242				t.Fatalf("data file byte %d changed", i)
243			}
244		}
245	
246		// 段标识未被占用：同一 ID 修正内容后导入成功。
247		if _, err := m.ImportSegment(Segment{ID: "s2", Frames: []Frame{
248			{Time: 2, Observations: []Observation{{ID: "L", X: 0}}},
249		}}); err != nil {
250			t.Fatalf("segment id consumed by failed import: %v", err)
251		}
252		// 失败没有消耗再现编号：L 的新出现仍是第 2 次，计数从 1 开始。
253		h, _ = m.LandmarkAppearances("L")
254		if len(h.Appearances) != 2 {
255			t.Fatalf("want 2 appearances, got %d: %+v", len(h.Appearances), h)
256		}
257		if h.Appearances[0].Number != 1 || h.Appearances[0].Active {
258			t.Fatalf("occurrence 1 changed: %+v", h.Appearances[0])
259		}
260		a2 := h.Appearances[1]
261		if a2.Number != 2 || !a2.Active || a2.Landmark.Count != 1 || a2.Landmark.X != 1e308 || a2.Landmark.Y != 0 {
262			t.Fatalf("reappearance = %+v, want #2 active count 1 at (1e308,0)", a2)
263		}
264	
265		// 落盘结果一致：重开后状态相同，且 s2 已作为成功段记录。
266		if err := m.Close(); err != nil {
267			t.Fatal(err)
268		}
269		m2, err := Open(path)
270		if err != nil {
271			t.Fatal(err)
272		}
273		defer m2.Close()
274		cur, _ = m2.CurrentPose()
275		if cur.Time != 2 {
276			t.Fatalf("after reopen current time = %d", cur.Time)
