280			t.Fatalf("after reopen appearances: %+v %v", h2, err)
281		}
282		// 同 ID 同内容重复导入返回首次结果。
283		if _, err := m2.ImportSegment(Segment{ID: "s2", Frames: []Frame{
284			{Time: 2, Observations: []Observation{{ID: "L", X: 0}}},
285		}}); err != nil {
286			t.Fatalf("duplicate import after reopen: %v", err)
287		}
288	}
289	
290	// 大坐标本身不受限制：位姿在 1e308 处保持有限即接受，同一路标连续两次
291	// 转换到同一地图坐标 (1e308,0) 合并后仍是 (1e308,0)、次数 2。
